package org.sqlcj.io;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.InvalidPathException;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Optional;

/**
 * Records the generated files of one package of one successful run and deletes
 * the files a previous run of that package recorded that this run did not
 * produce.
 *
 * <p>One manifest governs one {@code java.package} inside one {@code java.out}
 * and sits in the directory of that package, so configurations with different
 * packages may share an output directory. It begins with a notice that says
 * sqlcj owns it, followed by the line that names the configuration file owning
 * the package, and then one generated file path per line, relative to the
 * output directory with {@code /} between its name elements, so a manifest
 * written on one filesystem reads the same on another.
 *
 * <p>A manifest is read by the same rule whichever sqlcj wrote it: the owning
 * configuration is the first {@code # config: } line before the first entry,
 * every other line beginning {@code #} is ignored, and every other line is an
 * entry. A manifest without an owner line before its first entry was edited,
 * because sqlcj never writes one, and is reported instead of read.
 *
 * <p>Only a file that carries the generated-code notice is deleted, so an entry
 * a reader added by hand cannot cost a file sqlcj did not write.
 */
public final class GeneratedOutputManifest {

    /** The manifest file name, inside the generated package's directory. */
    public static final String FILE_NAME = "sqlcj-manifest.txt";

    /** The start of the line that names the owning configuration. */
    private static final String CONFIGURATION_PREFIX = "# config: ";

    /** The start of every line a manifest states about itself. */
    private static final String COMMENT_PREFIX = "#";

    /**
     * The notice every manifest begins with, which names its writer and states
     * what the next run does with it and when deleting it is safe.
     */
    private static final String NOTICE = """
        # Code generated by sqlcj. DO NOT EDIT.
        # sqlcj reads this file when it next generates this package: it deletes the
        # files listed below that it no longer generates, and it refuses to generate
        # this package from any configuration file other than the one named below.
        # This file is safe to delete only together with the files it lists, for
        # example with the whole output directory.
        """;

    /** The configuration and the entries one manifest holds. */
    public record Contents(String configuration, List<String> entries) {
    }

    /**
     * The owning configuration one manifest records: the configuration file's
     * path relative to the output directory, with {@code /} between its name
     * elements, so an output directory generated on another machine names the
     * same configuration file.
     */
    public String configuration(Path outputDirectory, Path configFile) {
        return entry(
            outputDirectory.toAbsolutePath()
                .normalize()
                .relativize(configFile.toAbsolutePath().normalize())
        );
    }

    /**
     * The contents of the manifest a previous run of this package wrote, or
     * nothing when the package holds no manifest.
     *
     * <p>A manifest whose owner line no longer comes before its first entry was
     * edited, an empty manifest and one of comment lines alone included, and is
     * reported rather than read as owned by no configuration.
     */
    public Optional<Contents> read(Path outputDirectory, String packageName) throws IOException {
        Path manifestPath = manifestPath(outputDirectory, packageName);

        if (!Files.exists(manifestPath)) {
            return Optional.empty();
        }

        List<String> lines;

        try {
            lines = Files.readAllLines(manifestPath, StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new IOException(
                "Cannot read output manifest: %s: %s"
                    .formatted(manifestPath, FileSystemReason.of(e)),
                e
            );
        }

        return Optional.of(contents(manifestPath, lines));
    }

    /**
     * Deletes every generated file the previous manifest listed that this run
     * did not produce, and nothing else. An entry that does not name a regular
     * file inside the output directory, or that names a file without the
     * generated-code notice, is left alone.
     */
    public void deleteStale(
        Path outputDirectory,
        List<String> previousEntries,
        List<Path> generatedPaths
    ) throws IOException {
        List<String> producedEntries = entries(generatedPaths);

        for (String previousEntry : previousEntries) {
            if (producedEntries.contains(previousEntry)) {
                continue;
            }

            deleteStaleEntry(outputDirectory, previousEntry, generatedPaths);
        }
    }

    /**
     * Records the notice, the owning configuration, and the generated paths of
     * one successful run of one package, one entry per line.
     */
    public void write(
        Path outputDirectory,
        String packageName,
        String configuration,
        List<Path> generatedPaths
    ) throws IOException {
        Path manifestPath = manifestPath(outputDirectory, packageName);

        StringBuilder content = new StringBuilder()
            .append(NOTICE)
            .append(CONFIGURATION_PREFIX)
            .append(configuration)
            .append('\n');

        entries(generatedPaths)
            .stream()
            .sorted()
            .forEach(entry -> content.append(entry).append('\n'));

        try {
            Files.createDirectories(manifestPath.getParent());

            Files.writeString(
                manifestPath,
                content,
                StandardCharsets.UTF_8,
                StandardOpenOption.CREATE,
                StandardOpenOption.TRUNCATE_EXISTING
            );
        } catch (IOException e) {
            throw new IOException(
                "Cannot write output manifest: %s: %s"
                    .formatted(manifestPath, FileSystemReason.of(e)),
                e
            );
        }
    }

    /**
     * The contents one manifest states: the owning configuration, which is the
     * first {@code # config: } line before the first entry, and every line that
     * is neither that line nor another line beginning {@code #}, in order. No
     * generated path begins with {@code #}, because every entry begins with a
     * package name.
     */
    private Contents contents(Path manifestPath, List<String> lines) throws IOException {
        String configuration = null;
        List<String> entries = new ArrayList<>();

        for (String line : lines) {
            if (line.startsWith(COMMENT_PREFIX)) {
                if (
                    configuration == null
                        && entries.isEmpty()
                        && line.startsWith(CONFIGURATION_PREFIX)
                ) {
                    configuration = line.substring(CONFIGURATION_PREFIX.length());
                }

                continue;
            }

            entries.add(line);
        }

        if (configuration == null) {
            throw new IOException(
                ("Edited output manifest: %s: no '%s' line comes before its first entry; "
                    + "restore it, or delete it together with the files it lists")
                    .formatted(manifestPath, CONFIGURATION_PREFIX)
            );
        }

        return new Contents(configuration, List.copyOf(entries));
    }

    /**
     * Deletes one stale entry, skipping an entry that does not name a regular
     * file inside the output directory, an entry that names a file this run
     * wrote, which a rename differing only by case produces on a
     * case-insensitive filesystem, and an entry that names a file without the
     * generated-code notice, which sqlcj did not write.
     */
    private void deleteStaleEntry(
        Path outputDirectory,
        String entry,
        List<Path> generatedPaths
    ) throws IOException {
        Path relativePath = relativePath(entry);

        if (relativePath == null) {
            return;
        }

        Path file = outputDirectory.resolve(relativePath);

        if (!Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS)) {
            return;
        }

        try {
            if (isGenerated(file, outputDirectory, generatedPaths)) {
                return;
            }
        } catch (IOException e) {
            throw staleFailure(file, e);
        }

        if (!GeneratedNotice.begins(file)) {
            return;
        }

        try {
            Files.delete(file);
        } catch (IOException e) {
            throw staleFailure(file, e);
        }
    }

    /** The failure of deleting one stale generated file. */
    private IOException staleFailure(Path file, IOException e) {
        return new IOException(
            "Cannot delete stale generated file: %s: %s"
                .formatted(file, FileSystemReason.of(e)),
            e
        );
    }

    /**
     * The relative path of one manifest entry, or {@code null} when the entry
     * is not a normalized relative path that stays inside the output
     * directory.
     */
    private Path relativePath(String entry) {
        if (entry.isEmpty()) {
            return null;
        }

        Path path;

        try {
            path = Path.of(entry);
        } catch (InvalidPathException e) {
            return null;
        }

        if (path.getRoot() != null) {
            return null;
        }

        if (path.getName(0).toString().equals("..")) {
            return null;
        }

        if (!entry.equals(entry(path.normalize()))) {
            return null;
        }

        return path;
    }

    private boolean isGenerated(
        Path file,
        Path outputDirectory,
        List<Path> generatedPaths
    ) throws IOException {
        for (Path generatedPath : generatedPaths) {
            if (Files.isSameFile(file, outputDirectory.resolve(generatedPath))) {
                return true;
            }
        }

        return false;
    }

    private List<String> entries(List<Path> generatedPaths) {
        List<String> entries = new ArrayList<>(generatedPaths.size());

        for (Path generatedPath : generatedPaths) {
            entries.add(entry(generatedPath));
        }

        return entries;
    }

    /** One entry, joining the path's name elements with {@code /}. */
    private String entry(Path path) {
        StringBuilder entry = new StringBuilder();

        for (Path name : path) {
            if (!entry.isEmpty()) {
                entry.append('/');
            }

            entry.append(name);
        }

        return entry.toString();
    }

    /** The manifest of one package, inside that package's own directory. */
    private Path manifestPath(Path outputDirectory, String packageName) {
        String[] segments = packageName.split("\\.");

        return outputDirectory
            .resolve(Path.of(segments[0], Arrays.copyOfRange(segments, 1, segments.length)))
            .resolve(FILE_NAME);
    }
}
